"use strict";(self.webpackChunkwebsite=self.webpackChunkwebsite||[]).push([[8130],{7735:e=>{e.exports=JSON.parse('{"archive":{"blogPosts":[{"id":"1.5.2 Update","metadata":{"permalink":"/blog/1.5.2 Update","source":"@site/blog/2025-12-24-update.md","title":"1.5.2 Update","description":"MEW - 1.5.2 Update","date":"2025-12-24T00:00:00.000Z","tags":[{"inline":true,"label":"December","permalink":"/blog/tags/december"}],"readingTime":0.77,"hasTruncateMarker":true,"authors":[{"name":"Biggie404","title":"Author and maintainer of the Mojave Express Wabbajack.","url":"https://github.com/mojaveexpressguide","imageURL":"https://github.com/mojaveexpressguide.png","key":"Biggie404","page":null}],"frontMatter":{"slug":"1.5.2 Update","title":"1.5.2 Update","authors":"Biggie404","tags":["December"]},"unlisted":false,"nextItem":{"title":"1.5.1 Update","permalink":"/blog/1.5.1 Update"}},"content":"**MEW - 1.5.2 Update**\\n\\n**ADDED:**\\n- Pip-Boy Screen Always On (No Plugin) - Issues should be fixed\\n- Hit - Crafting Animations\\n- Wild Wasteland Alien Encounter\\n\\n---\\n\\n**REMOVED:**\\n- Mojave Raiders - No NPC Throwing Weapon Consumption - Unbalanced\\n- Clear Scope for B42 Optics - Has some small issues with certain weapons\\n- Holo Panel Map - Causes the black pipboy with Realtime PipBoy Map. You can add this back if you want.\\n\\n---\\n\\n**FIXED/CHANGED:**\\n- Followers Outpost door link\\n- Fixed some clipping objects in Prospector Saloon and Ranger Andy\'s bungalow\\n- Fixed some issues with Strip 2026 and Revised Mojave\\n- Actually placed Greased Lightning\\n- Updated some iron sight alignments\\n- Halved backpack spawn chance on NPC\'s\\n- Slight nerfs to NPC ranges\\n\\n---\\n\\n**UPDATED:**\\n\\n- Realtime PipBoy Map - ESPless\\n- New Vegas Mesh Improvement Mod - NVMIM\\n- NPCs Sprint kNVSE - ESPless\\n- Animated Moments - ESPless\\n- Enhanced Movement\\n- Dead Man\'s Stash\\n- Modern Help Menu - ESPless\\n- lStewieAl\'s Tweaks and Engine Fixes\\n\\n---\\n\\n**SAFE TO UPDATE MID-SAVE**\\n\\nRead [Updating MEW](https://mojaveexpressguide.com/docs/Updating%20MEW).\\n\\n\x3c!-- truncate --\x3e"},{"id":"1.5.1 Update","metadata":{"permalink":"/blog/1.5.1 Update","source":"@site/blog/2025-12-21-update.md","title":"1.5.1 Update","description":"MEW - 1.5.1 Update","date":"2025-12-21T00:00:00.000Z","tags":[{"inline":true,"label":"December","permalink":"/blog/tags/december"}],"readingTime":0.6,"hasTruncateMarker":true,"authors":[{"name":"Biggie404","title":"Author and maintainer of the Mojave Express Wabbajack.","url":"https://github.com/mojaveexpressguide","imageURL":"https://github.com/mojaveexpressguide.png","key":"Biggie404","page":null}],"frontMatter":{"slug":"1.5.1 Update","title":"1.5.1 Update","authors":"Biggie404","tags":["December"]},"unlisted":false,"prevItem":{"title":"1.5.2 Update","permalink":"/blog/1.5.2 Update"},"nextItem":{"title":"1.5 Update","permalink":"/blog/1.5 Update"}},"content":"**MEW - 1.5.1 Update**\\n\\n**ADDED:**\\n- One Tweak - For convenience\\n- Lip Motion Singing\\n- ySI - Additional Icons\\n\\n---\\n\\n**FIXED/CHANGED:**\\n- Enabled some accidentally disabled mods for the MO2 Performance Preset\\n- Decompressed all records\\n- Fixed Jacklyn being purple\\n- Fixed 2 weapon meshes missing\\n- Fixed some NPC\'s having no clothing\\n- Further adjustments to levelled lists\\n- Changed Veronica Outfit Replacer from Scavenger to Recon version - Due to Scavenger using a vault suit underneath the hood.\\n- Improved some iron sight alignments\\n\\n---\\n\\n**UPDATED:**\\n\\n- Weapon Based Hands Clip Distance\\n- JLM Grab Tweak\\n- New Vegas Mesh Improvement Mod - NVMIM\\n- Point That Somewhere Else\\n- Colorful Icons Support\\n- Dead Man\'s Stash\\n- Pip-Boy UI Tweaks\\n- Overcharge - Energy Weapons Evolved\\n\\n---\\n\\n**SAFE TO UPDATE MID-SAVE**\\n\\nRead [Updating MEW](https://mojaveexpressguide.com/docs/Updating%20MEW).\\n\\n\x3c!-- truncate --\x3e"},{"id":"1.5 Update","metadata":{"permalink":"/blog/1.5 Update","source":"@site/blog/2025-12-18-update.md","title":"1.5 Update","description":"MEW - 1.5 Update","date":"2025-12-18T00:00:00.000Z","tags":[{"inline":true,"label":"December","permalink":"/blog/tags/december"}],"readingTime":3.57,"hasTruncateMarker":true,"authors":[{"name":"Biggie404","title":"Author and maintainer of the Mojave Express Wabbajack.","url":"https://github.com/mojaveexpressguide","imageURL":"https://github.com/mojaveexpressguide.png","key":"Biggie404","page":null}],"frontMatter":{"slug":"1.5 Update","title":"1.5 Update","authors":"Biggie404","tags":["December"]},"unlisted":false,"prevItem":{"title":"1.5.1 Update","permalink":"/blog/1.5.1 Update"},"nextItem":{"title":"1.4 Update","permalink":"/blog/1.4 Update"}},"content":"**MEW - 1.5 Update**\\n\\nBig update focused on content, balancing and difficulty **REQUIRES A NEW SAVE**.\\n\\nNew armours and weapons have been integrated and distributed into the world. Many of these are levelled.\\n\\nThere will probably be some changes you like and some you hate. Expect more updates to fix any issues and continued balance changes. Future small updates will be save compatible.\\n\\n**ADDED:**\\n\\n- B42 HOT BNB\\n- CIBS - Customizable Integrated Backpack System\\n- Canvas Backpacks - FNV - TTW\\n- Spice of Life Vanilla Bodies Patched - (Integrated into MEW - Armours)\\n- DVA - Distributed Variety Armors - (Integrated into MEW - Armours)\\n- Tammers Armor Pack - (Integrated into MEW - Armours)\\n- FG\'s Armors For All - (Integrated into MEW - Armours)\\n- Better Benny Bodyguards\\n- Veronica Outfit Replacer - Scavenger\\n- Legion Armor Reflects Player Strength\\n- Supplementary Weapons Pack - (Integrated into MEW - Weapons)\\n- NS AK47 - (Integrated into MEW - Weapons)\\n- Hunting Revolver Iron Sights\\n- Clear Scope for B42 Optics\\n- Lighting Enhanced Normal Textures\\n- MCM Extender\\n- Depth Resolve - NVSE\\n- Vanilla Plus Particles\\n- Vanilla Plus AO\\n- Party Banter 2.0\\n- Slightly more interesting - Gun Runners - Lighter than the mod previously used\\n- Strip 2026 - This is an exclusive to MEW for now.\\n- Bison Steve Layout Fix\\n- Techatticup Uncut - Voiced Legion Quest Expansion\\n- Lucky Jim\'s Cache\\n- Goodsprings Mine\\n- Prospector Saloon - An Overhaul\\n- Modern Help Menu - ESPless\\n- Dynamic Camera Shake\\n- Realtime PipBoy Map - ESPless\\n- Modern Minimap - Requirement for Realtime PipBoy Map - ESPless\\n- Animated Location Discovery\\n- Holo Panel Map\\n- Dead Man\'s Stash\\n- Explosive Overhaul (ESPless)\\n- Mojave Raiders - No NPC Throwing Weapon Consumption\\n- Accurate NASA Stars\\n- Player Voiceset Project\\n- Quest XP Overhaul ESPless\\n- Better Geiger Counter Sounds\\n- Ed-E Sneak Animations\\n- Corpse Looting Restrictions\\n- Lip Motion Fix\\n\\n---\\n\\n**REMOVED:**\\n\\n- Enhanced Mojave Plus - Searchlight - It\'s been replaced by the Revised Mojave update\\n- DM\'s Gun Runners Gone Shootin - Although cool it has an unnecessarily large bsa, left over forms and out of place magazines.\\n- Functional Post Game Ending - It\'s just underwhelming. The game ends at hoover dam which you will never reach anyway.\\n- Quick Select - The mod is incompatible with B42 HOT BNB and the vanilla system is fine \\n- Quick Select Throwables - Necessary as the above has been removed.\\n- Walking Intertia - Gets annoying and does not work nicely with enhanced creatures.\\n- Subtle Camera Shake (NVSE) replaced by Dynamic Camera Shake\\n- Fixed NPC Karma Alignments - Weird balancing and karma is just weak in this game anyway.\\n- MCM BugFix 2 - Redundant with MCM Extender.\\n- Faction Disguise De-Scripter - No longer required due to EVEM update\\n- Pipboy Holo Panel ESPless Rebuild Patch - No longer needed with latest Holo Panel update.\\n- Pip-Boy Screen Always On (No Plugin) - Issues with Realtime PipBoy Map - ESPless\\n- Legion Armor Revamp Project 2.0 - Replaced by Legion Armor Reflects Player Strength\\n\\n---\\n\\n**FIXED/CHANGED:**\\n\\n- Many new weapons and armours have been integrated and distributed\\n- Removed the need to manually reload (Sounded better in theory)\\n- Changed Freeside Interiors to Freeside Interiors - No Sewers\\n- Changed Afterglow to Afterglow (No JIP) - For Stability\\n- Changed Lived-in Strip to Lived-in Casino\\n- Updated Stewie Tweaks\\n\\t- Added: Radiation Causes Radio Static\\n- Backpacks have been rebalanced\\n- Enabled bLowerXPRewards=1 in JSUE ini\\n- Enabled bNewSteakRecipes=1 in JSUE ini\\n- Changed default difficulty to Normal instead of Hard\\n\\n---\\n\\n**UPDATED:**\\n\\n- xNVSE\\n- Point That Somewhere Else\\n- Mojave Skylines - Exteriors\\n- JohnnyGuitar NVSE\\n- Consumables Widget\\n- Repurposed Combat Dialogue\\n- JohnnyGuitar NVSE\\n- Afterglow -- Neon illumination\\n- Explosion Reactions - ESPless\\n- Drowning Visuals - ESPless\\n- MCM Extender\\n- JohnnyGuitar NVSE\\n- Freeside Gates\\n- Revised Mojave\\n- Lived-In Strip\\n- Goodies\\n- Mojave Scenery Overhaul\\n- Meshes and Collision - Totally Enhanced Nifs (MAC-TEN)\\n- Freeside Interiors\\n- MCM Extender\\n- ShowOff xNVSE Plugin\\n- Ghouls Inflict Radiation Damage - ESPless\\n- Doctor\'s House\\n- LARP\\n- Mojave Scenery Overhaul\\n- Freeside Interiors\\n- The Great Mojave Interior Overhaul\\n- lStewieAl\'s Tweaks and Engine Fixes\\n- Better Brotherhood\\n- LOD Flicker Fix - NVSE\\n- Skinned Mesh Improvement Mod\\n- Enhanced Creatures\\n- Colorful Icons Support\\n- Consistent Pip-Boy Icons v4\\n- ySI - Additional Icons\\n- Explosion Reactions - ESPless\\n- Condition Meter Icons - espless\\n- Some UI Sounds (SUS)\\n- YUP\\n- YUPDate\\n- Balanced Discounts and Barter Fixes\\n- Unofficial Patch NVSE Plus\\n- B42 Weapon Inertia\\n- Essential Vanilla Enhancements Merged\\n- Depth of Field Fix - NVSE\\n- Lime\'s Fort Overhaul\\n- Skill Based Pickpocketing - ESPless\\n- Essential Vanilla Enhancements Merged - PINIS\\n- New Vegas Mesh Improvement Mod - NVMIM\\n- Advanced 3rd Person Camera ESPless\\n- WMIM - Iron Sights for Energy Weapons (ISEW)\\n- ATMOS Ambience Overhaul\\n\\n---\\n\\n**NOT SAFE TO UPDATE MID-SAVE** - Due to large changes from the goodies update, new strip mod and multiple levelled list changes.\\n\\nRead [Updating MEW](https://mojaveexpressguide.com/docs/Updating%20MEW).\\n\\n\x3c!-- truncate --\x3e"},{"id":"1.4 Update","metadata":{"permalink":"/blog/1.4 Update","source":"@site/blog/2025-08-31-update.md","title":"1.4 Update","description":"MEW - 1.4 Update","date":"2025-08-31T00:00:00.000Z","tags":[{"inline":false,"label":"August","permalink":"/blog/tags/August","description":"August"}],"readingTime":0.93,"hasTruncateMarker":true,"authors":[{"name":"Biggie404","title":"Author and maintainer of the Mojave Express Wabbajack.","url":"https://github.com/mojaveexpressguide","imageURL":"https://github.com/mojaveexpressguide.png","key":"Biggie404","page":null}],"frontMatter":{"slug":"1.4 Update","title":"1.4 Update","authors":"Biggie404","tags":["August"]},"unlisted":false,"prevItem":{"title":"1.5 Update","permalink":"/blog/1.5 Update"},"nextItem":{"title":"1.3 Update","permalink":"/blog/1.3 Update"}},"content":"**MEW - 1.4 Update**\\n\\n**ADDED:**\\n- Smart Ownership\\n- Simple Worthless Item Ownership Overhaul\\n- Off Limits\\n- Pipboy Holo Panel ESPless Rebuild Patch\\n- Faction Disguise De-Scripter\\n- Windows To The Soul\\n\\n---\\n\\n**REMOVED:**\\n- Natural Eyes (Windows To The Soul looks better)\\n- Retrievable Throwables Reforged (items can be duplicated)\\n- Better Transitions (Potential crashing issues)\\n- Vanilla Script Micro-Optimizations (breaks faction armour)\\n- ySI - Additional Icons (Potential crashing issues)\\n- Quick Select - ySI Additional Icons Support Patch\\n\\n---\\n\\n**FIXED/CHANGED:**\\n- Fixed facegen issues with AWOLP\\n- Fixed Lucky 38 disappearing\\n- Changed NVTF INI to avoid alt+tab issues\\n- Adjusted GRA weapon pricing again\\n- Edited PointThatSomewhereElse!.ini\\n- Lowered base carryweight back to 50 (default JSawyer)\\n- Removed reload and equip speed changes from Reload Reloaded\\n- Changed Dismemberment Tweaks to the plugin version (scriptrunner sucks)\\n- Adjusted Enhanced Creatures to make dodging creatures attacks slightly harder\\n- Reduced sprint speed by 5%\\n- Changed walk key to L-Alt, Caps Lock still works as well\\n\\n---\\n\\n**UPDATED:**\\n\\n- Lived-In Freeside\\n- YUPDate - YUP Tweaks and Fixes\\n- Nuclear LOD\\n- Mojave Skylines - Exteriors\\n- Mojave Skylines - Lights of Vegas\\n- Curated Tweaks and Restorations\\n\\n---\\n\\n**SAFE TO UPDATE MID-SAVE**\\n\\nRead [Updating MEW](https://mojaveexpressguide.com/docs/Updating%20MEW).\\n\\n\x3c!-- truncate --\x3e"},{"id":"1.3 Update","metadata":{"permalink":"/blog/1.3 Update","source":"@site/blog/2025-08-27-update.md","title":"1.3 Update","description":"MEW - 1.3 Update","date":"2025-08-27T00:00:00.000Z","tags":[{"inline":false,"label":"August","permalink":"/blog/tags/August","description":"August"}],"readingTime":1.57,"hasTruncateMarker":true,"authors":[{"name":"Biggie404","title":"Author and maintainer of the Mojave Express Wabbajack.","url":"https://github.com/mojaveexpressguide","imageURL":"https://github.com/mojaveexpressguide.png","key":"Biggie404","page":null}],"frontMatter":{"slug":"1.3 Update","title":"1.3 Update","authors":"Biggie404","tags":["August"]},"unlisted":false,"prevItem":{"title":"1.4 Update","permalink":"/blog/1.4 Update"},"nextItem":{"title":"1.2+ Update","permalink":"/blog/1.2+ Update"}},"content":"**MEW - 1.3 Update**\\n\\n**ADDED:**\\n- Famine\\n- Wasted Rock Normals\\n- Quick Select - ySI Additional Icons Support Patch\\n- Consumables Widget\\n- Parallax Shaders - Objects\\n- Vanilla Objects Parallaxed\\n- MAPMO Hardcore Needs - Consumable Widget Style Icon Gauges\\n- hNVSE\\n- Mojave Skylines - Exteriors\\n- Mojave Skylines - Lights of Vegas\\n- Lived-In Freeside\\n- Zion landscape enhanced\\n- Hit - B42 Inject - Sunset Sarsaparilla Animations\\n- Hit - B42 Inject - Meat Animations\\n- Hit - B42 Inject - Water Animations\\n- Hit - B42 Inject - Liquid Courage\\n- Hit - B42 Inject - Assorted Items 1\\n- Van Graff Overhaul Overcharged - TOTNW Holo Panel patch\\n\\n---\\n\\n**REMOVED:**\\n- Sweets Scarcity\\n- B42 Dropmag - I think this may cause crashes\\n- Raiderfolk Mutated Raiders - Although cool I\'m not sure they really fit\\n- Better Strip View\\n- Consistent Light Pollution(GIR)\\n- Nipton Black smoke (GIR)\\n- Simple Freeside Overhaul\\n- A Little More Lamplight - It\'s going to be integrated into Revised Mojave soon\\n\\n---\\n\\n**CHANGED:**\\n- Stewie Tweaks - Changes:\\n    - Grabbing owned items now makes NPCs mad\\n    - Disabled companion kill cam\\n    - Disabled container open on lock pick\\n    - Disabled door open on lock pick\\n    - Show Tagged skills bold\\n    - No recurring challenges\\n\\n- Actually (actually) added the performance preset to MO2\\n- AWOLP - Removed leftovers, fixed some small issues and lowered some trooper ghoul HPs\\n- Updated all placed GRA weapons HP and values\\n- Fixed some small issues with lived in strip\\n- Fixed some issues with TGMIO and Revised Mojave\\n- Lowered radiation damage from certain creatures by half\\n- Removed reload and equip adjustments from Reload Reloaded\\n\\n---\\n\\n**UPDATED:**\\n- Enhanced FOV - ESPless\\n- Advanced 3rd Person Camera ESPless\\n- 3rd Person Aim Fix - ESPless\\n- Point That Somewhere Else - NPCs react to weapons\\n- ySI - Additional Icons\\n- YUPDate - YUP Tweaks and Fixes\\n- Weapon Based Hands Clip Distance\\n- Ultimate Edition ESM Fixes Remastered\\n- DM\'s Gun Runners Gone Shootin\\n- Dismemberment Tweaks\\n- Quick Select - A Zelda BOTW Style Quick Menu\\n- Quick Select Throwables\\n- Condition Meter Icons - espless\\n- ySI - Additional Icons\\n- Items Transformed - Enhanced Meshes (ITEM)\\n- NVTF - New Vegas Tick Fix\\n\\n---\\n\\n**SAFE TO UPDATE MID-SAVE**\\n\\nRead [Updating MEW](https://mojaveexpressguide.com/docs/Updating%20MEW).\\n\\n\x3c!-- truncate --\x3e"},{"id":"1.2+ Update","metadata":{"permalink":"/blog/1.2+ Update","source":"@site/blog/2025-07-31-update.md","title":"1.2+ Update","description":"MEW - 1.2+ Update","date":"2025-07-31T00:00:00.000Z","tags":[{"inline":false,"label":"July","permalink":"/blog/tags/july","description":"July"}],"readingTime":1.82,"hasTruncateMarker":true,"authors":[{"name":"Biggie404","title":"Author and maintainer of the Mojave Express Wabbajack.","url":"https://github.com/mojaveexpressguide","imageURL":"https://github.com/mojaveexpressguide.png","key":"Biggie404","page":null}],"frontMatter":{"slug":"1.2+ Update","title":"1.2+ Update","authors":"Biggie404","tags":["July"]},"unlisted":false,"prevItem":{"title":"1.3 Update","permalink":"/blog/1.3 Update"},"nextItem":{"title":"1.1 Update","permalink":"/blog/1.1 Update"}},"content":"**MEW - 1.2+ Update**\\n\\n**ADDED:**\\n- Revised Mojave\\n- Desert Interiors - Atmos Compatible Version\\n- Freeside Interiors\\n- Simple AI Merge\\n- Enhanced Creatures\\n- Revamped Fiend Headgear\\n- LARP - Legion Armor Revamp Project\\n- Better Transitions\\n- Stim Your Friends - Fallout 4 Style NPC Stim - ESPless\\n- Sweet Scarcity - (Values should be similar to famine but may be tweaked in the future)\\n- ySI - Additional Icons\\n- Fallout 3 Karma\\n- Added support for Epic Games version\\n- Added Performance Preset - (More info on the Performance & Optimisation page)\\n\\n**REMOVED:**\\n- ML Utilities Checker - (MEW Patches now contains a version made by Qolore7)\\n- CBBE due to Enhanced Creatures changes being preferred\\n- Famine - Replaced by Sweet Scarcity\\n- New Vegas Suburban Overhaul - Due to conflicts with Revised Mojave\\n- Lived in AIO - Due to conflicts with Revised Mojave\\n- 16 LOD mods that are only required for LOD generation\\n- Consumables Widget - Issue with consumables staying on screen after death\\n- Bash Perks Hidden - Changes integrated into MEW - Tweaks\\n- PerkOut - SkilledAlt - Changes integrated into MEW - Tweaks\\n- Vanilla Underwear Replacer\\n\\n**TWEAKED:**\\n- Fixed small issue with Pipboy Holo Panel ESPless breaking when selecting unarmed with Quick Select in power armour\\n- MEW - Patches \\n    - Includes utility mod checker by Qolore7\\n    - Fixed issue with Pyromaniac perk not using the explosives skill\\n    - Changed some Lock difficulties\\n    - Made levelling up actually 50% slower\\n- MEW - INI\'s and Configs\\n    - Reduced base sprint speed to 60% but boosted agility speed scaling\\n    - Added Enhanced Creatures INI\\n\\n\\n**UPDATED:**\\n- New Vegas Script Extender (NVSE xNVSE)\\n- NVTF - (Stutter should be reduced further)\\n- Meshes and Collision - Totally Enhanced Nifs (MAC-TEN)\\n- YUPDate - YUP Tweaks and Fixes\\n- Vanilla Plus Terrain\\n- MAPMO - Main and Pause Menus Overhaul\\n- Companion Map Icons - ESPless\\n- PipBoy UI Tweaks\\n- 3D Grenade Indicator - ESPless\\n- Sleep Wait Hardcore Needs\\n- ySI - Contextual Prompts\\n- Local Map Overhaul\\n- Enhanced Movement\\n- Locks Overhaul\\n- Ghouls Inflict Radiation Damage - ESPless\\n- Point That Somewhere Else\\n- Raiderfolk Mutated Raiders\\n- NPCs Sprint kNVSE\\n- Lived-In Strip\\n- Mojave Scenery Overhaul\\n- Curated Tweaks and Restorations\\n- Goodies\\n- FPGE - Functional Post Game Ending\\n- Advanced 3rd Person Camera ESPless\\n- Radiation Visuals - ESPless\\n- Crafting and Repair Animations\\n- Explosion Reactions - ESPless\\n- Vanilla Script Micro-Optimizations\\n- MEW - Object LOD Output - (New rock texture colour and new black rock mesh exclusive to MEW)\\n\\n**SAFE TO UPDATE MID-SAVE** - (Hopefully)\\n\\nRead [Updating MEW](https://mojaveexpressguide.com/docs/Updating%20MEW)\\n\\n\x3c!-- truncate --\x3e"},{"id":"1.1 Update","metadata":{"permalink":"/blog/1.1 Update","source":"@site/blog/2025-06-28-update.md","title":"1.1 Update","description":"MEW - 1.1 Update","date":"2025-06-28T00:00:00.000Z","tags":[{"inline":false,"label":"June","permalink":"/blog/tags/June","description":"June"}],"readingTime":0.39,"hasTruncateMarker":true,"authors":[{"name":"Biggie404","title":"Author and maintainer of the Mojave Express Wabbajack.","url":"https://github.com/mojaveexpressguide","imageURL":"https://github.com/mojaveexpressguide.png","key":"Biggie404","page":null}],"frontMatter":{"slug":"1.1 Update","title":"1.1 Update","authors":"Biggie404","tags":["June"]},"unlisted":false,"prevItem":{"title":"1.2+ Update","permalink":"/blog/1.2+ Update"},"nextItem":{"title":"Initial Release","permalink":"/blog/initial-release"}},"content":"**MEW - 1.1 Update**\\n\\nA small update to mainly account for mod updates.\\n\\n**User Interface**\\n- **Updated:** Colorful Icons Support\\n\\n**Gameplay Overhauls**\\n- **Removed:** Faction Disguise De-Scripter (It\'s not working as intended)\\n\\n**Difficulty Overhauls**\\n- **Updated:** Skill Based Pickpocketing\\n- **Updated:** STALKER Barter\\n\\n**NPC Overhauls**\\n- **Updated:** NPCs Sprint kNVSE - ESPless\\n\\n**Content**\\n- **Updated:** Curated Tweaks and Restorations\\n\\nFixed issue with some females eyes like Sunny Smiles and Trudy.\\n\\n**SAFE TO UPDATE MID-SAVE**\\n\\nRead **[Updating MEW](https://mojaveexpressguide.com/docs/Updating%20MEW)**.\\n\\n\x3c!-- truncate --\x3e"},{"id":"initial-release","metadata":{"permalink":"/blog/initial-release","source":"@site/blog/2025-06-25-initial-release.md","title":"Initial Release","description":"Release of the slop","date":"2025-06-25T00:00:00.000Z","tags":[{"inline":false,"label":"June","permalink":"/blog/tags/June","description":"June"}],"readingTime":0.03,"hasTruncateMarker":true,"authors":[{"name":"Biggie404","title":"Author and maintainer of the Mojave Express Wabbajack.","url":"https://github.com/mojaveexpressguide","imageURL":"https://github.com/mojaveexpressguide.png","key":"Biggie404","page":null}],"frontMatter":{"slug":"initial-release","title":"Initial Release","authors":"Biggie404","tags":["June"]},"unlisted":false,"prevItem":{"title":"1.1 Update","permalink":"/blog/1.1 Update"}},"content":"Release of the slop\\n\\n\x3c!-- truncate --\x3e"}]}}')}}]);